Route::get('/email/verify/{id}/{hash}', function (EmailVerificationRequest $request) { $request->fulfill(); return redirect()->route($request->user()->isSeller() ? 'seller.status' : 'shop')->with('status', 'Email address verified.'); })->middleware(['auth', 'signed', 'throttle:6,1'])->name('verification.verify');
Route::post('/email/verification-notification', function (Request $request) {
    try {
        $request->user()->sendEmailVerificationNotification();
    } catch (\Symfony\Component\Mailer\Exception\TransportExceptionInterface $exception) {
        report($exception);

        return back()->withErrors(['email' => 'We could not send the verification email. The mail provider rejected the sending account or could not be reached. Check the SMTP settings, then try again.']);
    }

    $message = config('mail.default') === 'log'
        ? 'Verification email created locally. Email delivery is not configured, so no message was sent to your inbox.'
        : 'A new verification link was sent. Check your inbox and spam folder.';

    return back()->with('status', $message);
})->middleware(['auth', 'throttle:6,1'])->name('verification.send');
